  src: url("fonts/source-serif-4-latin-400-normal.woff2") format("woff2");
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Inter", sans-serif;
  font-size: 16px;
  line-height: 1.55;
  color: #26302f;
  background: #f7f8f6;
}

a {
  color: inherit;
}

.site-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 22px 64px;
}

.logo {
  font-family: "Source Serif 4", serif;
  font-size: 24px;
  text-decoration: none;
}

.site-nav a {
  margin-left: 28px;
  text-decoration: none;
  font-size: 20px;
}

.hero {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 64px;
  padding: 48px 64px 32px;
}

.hero-text {
  max-width: 600px;
}

h1 {
  margin: 0 0 14px;
  font-size: 22px;
  font-weight: 400;
  line-height: 1.35;
  color: #6b7574;
}

.lead {
  margin: 0 0 28px;
  font-size: 20px;
  line-height: 1.5;
  color: #26302f;
}

.button {
  display: inline-block;
  padding: 11px 20px;
  border-radius: 6px;
  background: #2d5d5a;
  color: #ffffff;
  text-decoration: none;
  font-weight: 500;
}

.search {
  flex: 0 0 340px;
  padding: 22px;
  border: 1px solid #dfe3e0;
  border-radius: 8px;
  background: #ffffff;
}

.search-title {
  margin-bottom: 14px;
  font-weight: 500;
}

.search label {
  display: block;
  margin-bottom: 12px;
  font-size: 14px;
  color: #6b7574;
}

.search select,
.search input {
  display: block;
  width: 100%;
  margin-top: 4px;
  padding: 8px 10px;
  border: 1px solid #cfd5d2;
  border-radius: 6px;
  background: #ffffff;
  font: inherit;
  font-size: 16px;
  color: #26302f;
}

.search button {
  width: 100%;
  margin-top: 6px;
  padding: 10px;
  border: 1px solid #2d5d5a;
  border-radius: 6px;
  background: #ffffff;
  color: #2d5d5a;
  font: inherit;
  font-weight: 500;
}

.routes {
  padding: 0 64px;
}

h2 {
  margin: 0 0 10px;
  font-size: 16px;
  font-weight: 500;
}

.routes ul {
  max-width: 600px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.routes li {
  display: flex;
  justify-content: space-between;
  padding: 8px 0;
  border-top: 1px solid #dfe3e0;
  color: #6b7574;
}

.route-name {
  color: #26302f;
}

